package config

import("bufio";"context";"fmt";"os";"strconv";"strings";"time")

// Config contains boot-time onboarding settings.
type Config struct{OrganizationName string;ValidatorAddresses []string;ValidatorRootCA,IdentityStore,IdentityPassphraseEnv,Serial,Chassis,BoardID string;ControllerTimeout,RetryInitial,RetryMax time.Duration}
// Load reads the documented YAML subset used by this prototype.
func Load(ctx context.Context,path string)(Config,error){if err:=ctx.Err();err!=nil{return Config{},fmt.Errorf("load config: %w",err)};f,e:=os.Open(path);if e!=nil{return Config{},fmt.Errorf("open config: %w",e)};defer f.Close();m:=map[string]string{};var vs []string;list:=false;s:=bufio.NewScanner(f);for s.Scan(){l:=strings.TrimSpace(s.Text());if l==""||strings.HasPrefix(l,"#"){continue};if strings.HasPrefix(l,"- ")&&list{vs=append(vs,strings.TrimSpace(l[2:]));continue};if strings.HasSuffix(l,":"){list=strings.TrimSuffix(l,":")=="validator_addresses";continue};p:=strings.SplitN(l,":",2);if len(p)!=2{return Config{},fmt.Errorf("parse config line %q",l)};m[strings.TrimSpace(p[0])]=strings.Trim(strings.TrimSpace(p[1]),"\"'");list=false};if e=s.Err();e!=nil{return Config{},fmt.Errorf("scan config: %w",e)};req:=func(k string)(string,error){if m[k]==""{return "",fmt.Errorf("config %s: missing value",k)};return m[k],nil};org,e:=req("organization_name");if e!=nil{return Config{},e};root,e:=req("validator_root_ca");if e!=nil{return Config{},e};store,e:=req("identity_store");if e!=nil{return Config{},e};env,e:=req("identity_passphrase_env");if e!=nil{return Config{},e};serial,e:=req("serial");if e!=nil{return Config{},e};ch,e:=req("chassis");if e!=nil{return Config{},e};board,e:=req("board_id");if e!=nil{return Config{},e};if len(vs)==0{return Config{},fmt.Errorf("validator_addresses: empty list")};ms:=func(k string,d time.Duration)(time.Duration,error){if m[k]==""{return d,nil};n,e:=strconv.Atoi(m[k]);if e!=nil{return 0,fmt.Errorf("parse %s: %w",k,e)};return time.Duration(n)*time.Millisecond,nil};sec:=func(k string,d time.Duration)(time.Duration,error){if m[k]==""{return d,nil};n,e:=strconv.Atoi(m[k]);if e!=nil{return 0,fmt.Errorf("parse %s: %w",k,e)};return time.Duration(n)*time.Second,nil};ri,e:=ms("retry_initial_milliseconds",250*time.Millisecond);if e!=nil{return Config{},e};rm,e:=ms("retry_max_milliseconds",10*time.Second);if e!=nil{return Config{},e};ct,e:=sec("controller_timeout_seconds",10*time.Second);if e!=nil{return Config{},e};return Config{org,vs,root,store,env,serial,ch,board,ct,ri,rm},nil}
